function addVeh(id, type, o) { const T = TYPES[type]; state.veh[id] = Object.assign({ id, type, L: T.L, aFront: true }, o); const v = state.veh[id]; if (v.wt === undefined) v.wt = T.tare + (v.load ? v.load.t : 0); }
