  if (kind === 'couple') {
    if (a > 6) { s.money -= 120; s.rep -= 5; s.dayBad = true; toast(`Hard hit at ${a.toFixed(1)} mph! Car damaged: -$120 -5 rep. Couple under 4 mph.`, 'bad'); sfx('crash'); }
    else if (a > 4) { s.money -= 30; s.rep -= 2; toast(`Rough coupling at ${a.toFixed(1)} mph: -$30 -2 rep. Keep it under 4 mph.`, 'bad'); sfx('clank'); }
    else { toast(`Coupled (${a.toFixed(1)} mph).`, 'good'); sfx('clank'); }
  } else if (kind === 'bumper') {
    if (a > 3) { s.money -= 50; s.rep -= 3; s.dayBad = true; toast(`Hit the bumper at ${a.toFixed(1)} mph: -$50 -3 rep.`, 'bad'); sfx('crash'); }
    else if (a > 0.3) toast('Stopped against the bumper.');
  } else if (kind === 'foul') {
    if (a > 3) { s.money -= 80; s.rep -= 4; s.dayBad = true; toast(`Sideswiped a car at the switch (${a.toFixed(1)} mph): -$80 -4 rep.`, 'bad'); sfx('crash'); }
    else toast('Blocked: a car is fouling that switch.', 'bad');
  } else if (kind === 'edge') {
    if (a === 'nE' && NII.TOWNS.mattoon.south) askTravel(NII.TOWNS.mattoon.south);
    else toast(`End of the Mattoon test map (main line continues ${NODES[a].label}).`);
  } else if (kind === 'runthrough') {
    s.money -= 40; s.rep += REP.DERAIL; s.dayBad = true; toast(`Ran through switch ${NODES[a].tag} (${NODES[a].name}) lined the wrong way and derailed: -$40 ${REP.DERAIL} rep.`, 'bad'); sfx('crash');
  }
