function lookAt(x, y) { view.follow = false; const yy = y === undefined ? view.ys : Math.max(-80, Math.min(330, y)); view.x = x; view.v = Math.max(VMIN, Math.min(VMAX, imgY(yy))); view.ys = yy; }
