  const tA = up(A, h), tB = up(B, h);
  if (x0 > PV.XC) poly(g, [A, tA, [D[0], Math.min(tA[1], up(D, h)[1] + (h > 8 ? 99999 : 0))], D], col.side);
  else if (x1 < PV.XC) poly(g, [B, tB, [C[0], Math.min(tB[1], up(C, h)[1] + (h > 8 ? 99999 : 0))], C], col.side);
