    for (let i = 0; i < 18; i++) treeAt(1500 + R2() * (P.nE[0] - 1100), 326 + R2() * 500, 30 + R2() * 25);
    for (let i = 0; i < 14; i++) { const tx = 1360 + R2() * (P.nE[0] - 1200), ty = 45 + R2() * 140, th = 24 + R2() * 22; if (tx < P.E0[0] + 80 && ty < 140) continue; if (tx > P.bT[0] - 40 && tx < P.iM[0] + 30 && ty < 150) continue; treeAt(tx, ty, th); }
